#include "defines.hpp"

// include benchmark-specific definitions (N, M, DATA_TYPE, etc.)
#include "syr2k.hpp"

using num_t = DATA_TYPE;

namespace {

// basic dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// layout tuning (can be changed independently of the algorithm)
struct tuning {
	// C is N x N, indexed by (i, j)
	// Use row-major layout in logical (i, j): i (outer) x j (inner)
	// so that j is contiguous for a fixed i. This matches the inner
	// j-loop in the kernel and improves spatial locality / SIMD.
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec);

	// A is N x M, indexed by (i, k)
	// Keep k (outer) x i (inner): for a fixed k, all rows i are
	// contiguous, which is good for accesses A[j, k] where j varies.
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B is N x M, indexed by (i, k)
	// Same layout as A for the same reasons.
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec);
} tuning;

// initialization function
// C: i x j  (N x N)
// A: i x k  (N x M)
// B: i x k  (N x M)
