	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto n_len  = A | get_length<'i'>(); // corresponds to original 'n'
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	traverser(B).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto m_len  = B | get_length<'k'>(); // corresponds to original 'm'
		B[state] = (num_t)((i * k + 2) % m_len) / m_len;
	});

	// Initialize C: C[i][j] = ( (i * j + 3) % n ) / m
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto n_len  = C | get_length<'i'>(); // N
		auto m_len  = B | get_length<'k'>(); // M
		C[state] = (num_t)((i * j + 3) % n_len) / m_len;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Block size in the reduction dimension k. This is a tuning knob;
	// we choose it as a compile-time constant so that the compiler
	// can optimize the inner loops well.
	constexpr auto tile_k = noarr::lit<64>;

	// C: i x j
	// A: i x k
	// B: i x k

#pragma scop
	// ---------------------------------------------------------------------
	// Phase 1: scale the lower-triangular part of C by beta:
	//   for (i = 0..N-1)
	//     for (j = 0..N-1)
	//       if (j <= i) C[i][j] *= beta;
	//
	// Thanks to the row-major layout of C (i outer, j inner), the inner
	// j-loop now walks contiguous memory for each i, improving locality.
	// ---------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
		trav_i.template for_each<'j'>([=](auto state) {
			auto i_cur = get_index<'i'>(state);
			auto j_cur = get_index<'j'>(state);

			if (j_cur <= i_cur) {
				C[state] *= beta;
			}
		});
	});

	// ---------------------------------------------------------------------
	// Phase 2: rank-2k SYR2K update:
	//
	//   for (i = 0..N-1)
	//     for (k = 0..M-1)
	//       for (j = 0..N-1)
	//         if (j <= i)
	//           C[i][j] += A[j][k] * alpha * B[i][k]
	//                       + B[j][k] * alpha * A[i][k];
	//
	// We keep exactly the same algebraic form to preserve numerical
	// behavior, but:
	//   - we block the k-dimension with into_blocks_dynamic to improve
	//     cache locality on A and B,
	//   - we hoist A[i,k] and B[i,k] out of the inner j-loop so they
	//     are loaded once per (i, k),
	//   - we exploit that C is row-major in (i, j), so the inner j-loop
	//     is over contiguous elements of C.
	// ---------------------------------------------------------------------

	// Create a traverser that is blocked along k:
	//   - 'K' is the block index,
	//   - 'k' is the index within the block,
	//   - 'u' is a guard dimension that is length 1 for valid (K,k)
	//     pairs and 0 for padded ones in the last, partial block.
	auto blocked = traverser(C, A, B).order(
		into_blocks_dynamic<'k', 'K', 'k', 'u'>(tile_k)
	);

	// Loop nest:
	//   for i
	//     for K (k-blocks)
	//       for k in block(K)
	//         preload A[i,k], B[i,k]
	//         for j
	//           if (j <= i) update C[i,j]
	blocked.template for_dims<'i'>([=](auto trav_i) {
		// Fix i; loop over k-blocks
		trav_i.template for_dims<'K'>([=](auto trav_iK) {
			// For each i and k inside this K-block (u filters out padding)
			trav_iK.template for_dims<'k', 'u'>([=](auto trav_ik) {
				// State with current (i, k) (and K, u, ignored by A/B)
				auto state_ik = trav_ik.state();

				// A[i][k], B[i][k] reused for all j in this (i, k)
				num_t A_ik = A[state_ik];
				num_t B_ik = B[state_ik];

				// Now walk all j for this (i, k). With C laid out as
				// i (outer) x j (inner), this loop streams contiguously
				// through C's row i, and, because A/B are k-outer x i-inner,
				// accesses A[j,k] and B[j,k] are contiguous in memory as j varies.
				trav_ik.template for_each<'j'>([=](auto state) {
					auto i_cur = get_index<'i'>(state);
					auto j_cur = get_index<'j'>(state);

					// Only update the lower triangle, as in the original code
					if (j_cur <= i_cur) {
						// Build a state where the row index for A/B is j instead of i
						auto state_jk = state.template with<index_in<'i'>>(j_cur);

						// A[j][k], B[j][k]
						num_t A_jk = A[state_jk];
						num_t B_jk = B[state_jk];

						// Update C[i][j] with the same expression as the original
						// kernel to preserve floating-point behavior:
						//
						//   C[i][j] += A[j][k] * alpha * B[i][k]
						//              + B[j][k] * alpha * A[i][k];
						C[state] += A_jk * alpha * B_ik
						          + B_jk * alpha * A_ik;
					}
				});
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
