		// current i index (constant throughout all inner loops)
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// ---------------------------------------------------------------------
		// First loop nest:
		//   for (j = 0; j <= i; j++)
		//       C[i][j] *= beta;
		//
		// We keep the j-loop structure but avoid recomputing i from the state.
		// Upper-triangular entries (j > i) are left unchanged.
		// ---------------------------------------------------------------------
		trav_i.template for_each<'j'>([&](auto state) {
			auto j_cur = get_index<'j'>(state);

			if (j_cur <= i_idx) {
				C[state] *= beta;
			}
		});

		// ---------------------------------------------------------------------
		// Second loop nest:
		//   for (k = 0; k < M; k++)
		//     for (j = 0; j <= i; j++)
		//       C[i][j] += A[j][k] * alpha * B[i][k]
		//                  + B[j][k] * alpha * A[i][k];
		//
		// We keep exactly the same logical order of (i, k, j) as above but:
		//   - hoist A[i,k] and B[i,k] out of the inner j-loop,
		//   - precompute alpha*A[i,k] and alpha*B[i,k] once per (i,k).
		// ---------------------------------------------------------------------
