			// state_ik has indices (i, k), both fixed for this traversal
			auto state_ik = trav_k.state();

			const num_t A_ik = A[state_ik];
			const num_t B_ik = B[state_ik];

			// Pre-scale by alpha once per (i, k)
			const num_t alphaA_ik = alpha * A_ik;
			const num_t alphaB_ik = alpha * B_ik;

			// Inner j-loop: update C[i][j] for j <= i
			trav_k.template for_each<'j'>([&](auto state) {
				auto j_cur = get_index<'j'>(state);

				if (j_cur <= i_idx) {
					// Build a state where the row index for A/B is j instead of i:
					// this shares the same k index as 'state'.
					auto state_jk = state.template with<index_in<'i'>>(j_cur);

					// A[j][k], B[j][k] — thanks to i_vec ^ k_vec layout, varying j
					// for fixed k is unit-stride in memory.
					const num_t A_jk = A[state_jk];
					const num_t B_jk = B[state_jk];

					// Original expression:
					//   C += A_jk * alpha * B_ik + B_jk * alpha * A_ik;
					// Rewritten with precomputed alphaA_ik / alphaB_ik:
					//   C += A_jk * (alpha * B_ik) + B_jk * (alpha * A_ik);
					C[state] += A_jk * alphaB_ik + B_jk * alphaA_ik;
