// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k
	// B: i x k
	//
	// Optimized structure:
	//   * 3D tiling in i, j, k using into_blocks_dynamic
	//   * scale C by beta once per (i,j) before the k-reduction
	//   * hoist A[i,k], B[i,k] and pre-scale by alpha outside the inner j-loop
	//   * maintain the original triangular condition j <= i
	//
	// Tiling sizes are compile-time constants; tune for target cache/micro-arch.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 32;
	constexpr std::size_t tile_k = 32;

	// Total size in the i-dimension (needed for triangular tile culling)
	const std::size_t n = C | get_length<'i'>();

	// Block the three logical dimensions:
	//   'i' -> ('I' = block index, 'i' = intra-block, 's' = presence flag)
	//   'j' -> ('J', 'j', 't')
	//   'k' -> ('K', 'k', 'u')
