		into_blocks_dynamic<'i', 'I', 'i', 's'>(noarr::lit<tile_i>) ^
		into_blocks_dynamic<'j', 'J', 'j', 't'>(noarr::lit<tile_j>) ^
		into_blocks_dynamic<'k', 'K', 'k', 'u'>(noarr::lit<tile_k>());

#pragma scop
	// Traverser over *blocked* views of C, A, B.
