			trav_I.template for_dims<'J'>([=](auto trav_J) {
				// Tile coordinates (I,J) in the blocked space
				auto tile_state = trav_J.state();
				std::size_t I_idx = get_index<'I'>(tile_state);
				std::size_t J_idx = get_index<'J'>(tile_state);

				// Compute the global i-range covered by this I-tile
				std::size_t i_start = I_idx * tile_i;
				std::size_t i_end = i_start + tile_i;
				if (i_end > n) i_end = n;

				// Compute the global j-range start for this J-tile
				std::size_t j_start = J_idx * tile_j;

				// If the entire tile (I,J) lies strictly above the main diagonal,
				// i.e., j_start >= i_end, then all (i,j) in this tile have j > i
				// and can be skipped completely (both for scaling and update).
				if (j_start >= i_end)
					return;

				// -----------------------------------------------------------------
				// Phase 1: scale the (local) lower-triangular part of this tile
				//          by beta: C[i,j] *= beta for j <= i.
				// We iterate only over (i,j) in this tile; K/k/u stay implicit.
				// -----------------------------------------------------------------
				trav_J.template for_dims<'i', 's', 'j', 't'>([=](auto state) {
					auto i = get_index<'i'>(state);
					auto j = get_index<'j'>(state);

					if (j <= i) {
						C[state] *= beta;
					}
				});

				// -----------------------------------------------------------------
				// Phase 2: SYR2K update within this (I,J) tile.
				//
				// For each (i,j) with j <= i, we add:
				//   C[i,j] += alpha * sum_k ( A[j,k] * B[i,k] + B[j,k] * A[i,k] )
				//
				// We organize it as:
				//   for K (k-tiles)
				//     for (i,k) in (I,K) tile:
				//       preload a_ik = A[i,k], b_ik = B[i,k]
				//       alphaA_ik = alpha * a_ik
				//       alphaB_ik = alpha * b_ik
				//       for j in J-tile:
				//         if (j <= i):
				//           C[i,j] += A[j,k] * alphaB_ik + B[j,k] * alphaA_ik
				// -----------------------------------------------------------------
				trav_J.template for_dims<'K'>([=](auto trav_K) {
					// Fix K (a k-tile), then iterate over all valid (i,k) pairs
					// in this (I,K) tile.
					trav_K.template for_dims<'i', 's', 'k', 'u'>([=](auto trav_ik) {
						// State for the current (i,k) (plus tile/guard dims).
						auto state_ik = trav_ik.state();
						auto i = get_index<'i'>(state_ik);

						// Load A[i,k] and B[i,k] once per (i,k) and pre-scale by alpha.
						num_t A_ik = A[state_ik];
						num_t B_ik = B[state_ik];

						num_t alphaA_ik = alpha * A_ik;
						num_t alphaB_ik = alpha * B_ik;

						// Now iterate j within this (I,J,K,i,k) micro-tile.
						trav_ik.template for_dims<'j', 't'>([=](auto state) {
							auto j = get_index<'j'>(state);

							// Respect the lower-triangular domain.
							if (j <= i) {
								// state currently has indices (i, j, k, I, J, K, s, t, u, ...)
								// For A[j,k] and B[j,k], we need a state where the 'i' index
								// is j instead of i, but keep the same k (and tile coords).
								auto state_jk = state.template with<index_in<'i'>>(j);

								num_t A_jk = A[state_jk];
								num_t B_jk = B[state_jk];

								// C[i,j] += alpha * (A[j,k]*B[i,k] + B[j,k]*A[i,k])
								// implemented as:
								//   A[j,k] * alphaB_ik + B[j,k] * alphaA_ik
								// to hoist the multiplications by alpha.
								C[state] += A_jk * alphaB_ik + B_jk * alphaA_ik;
							}
						}); // end j,t in this (i,k) tile
					}); // end (i,s,k,u) in this (I,J,K) tile
				}); // end K in this (I,J) tile
			}); // end J
		}); // end I
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// scalar parameters
	num_t alpha;
	num_t beta;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// allocate bags for C, A, B with selected layouts and lengths
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syr2k(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// stop timer
