	// A: i x k
	// B: i x k

#pragma scop
	// Outer loop over i (rows of C). We iterate via the traverser so that
	// the loop structure is expressed in Noarr terms.
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
