		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// Inner loop over j (columns of C for this row i).
		// We still iterate the full [0, N) range, but we restrict the
		// computation to the lower triangle via j_idx <= i_idx.
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx    = get_index<'j'>(state_ij);

			// Only update the lower-triangular part (j <= i).
			// Entries j > i remain unchanged, exactly as in the original code.
			if (j_idx > i_idx)
				return;

			// Load C(i,j) *once*, apply beta scaling immediately, and then
			// accumulate the full symmetric rank-2k update in a scalar.
			num_t cij = C[state_ij] * beta;

			// Reduction over k for this fixed (i,j):
			//
			//   cij += alpha * sum_k ( A[j,k] * B[i,k] + B[j,k] * A[i,k] )
			//
