				auto state_ijk = trav_ijk.state();

				// For A[j,k] and B[j,k], we need the same 'k' as in state_ijk,
				// but with the row index 'i' replaced by j_idx. The 'j' index
				// in the state is irrelevant for A/B: they only care about
				// dimensions 'i' and 'k'.
				auto state_jk = state_ijk.template with<index_in<'i'>>(j_idx);

				// A[j,k], B[j,k]
				num_t A_jk = A[state_jk];
				num_t B_jk = B[state_jk];

				// A[i,k], B[i,k]  (i is the original row index in state_ijk)
				num_t A_ik = A[state_ijk];
				num_t B_ik = B[state_ijk];

