				// This is algebraically identical to the original expression:
				//   C[i][j] += A[j][k] * alpha * B[i][k]
				//             + B[j][k] * alpha * A[i][k];
				cij += A_jk * alpha * B_ik + B_jk * alpha * A_ik;
			});

